// Landing page: reveal-on-scroll, card glow, and every number pulled from numbers.json
// (generated by `make numbers`) with a live fallback to the running API.
(function () {
  const io = new IntersectionObserver(
    es =>
      es.forEach(e => {
        if (e.isIntersecting) {
          e.target.classList.add("in");
          io.unobserve(e.target);
        }
      }),
    { threshold: 0.12 }
  );
  document.querySelectorAll(".reveal").forEach(el => io.observe(el));
  document.querySelectorAll(".card").forEach(c =>
    c.addEventListener("pointermove", e => {
      const r = c.getBoundingClientRect();
      c.style.setProperty("--mx", e.clientX - r.left + "px");
      c.style.setProperty("--my", e.clientY - r.top + "px");
    })
  );
  const pct = x => (x == null ? "–" : Math.round(x * 100) + "%");
  const set = (k, v) => document.querySelectorAll(`[data-k="${k}"]`).forEach(el => (el.textContent = v));

  function countUp(el, to, suffix) {
    const t0 = performance.now(),
      dur = 1400;
    (function f(t) {
      const p = Math.min(1, (t - t0) / dur),
        e = 1 - Math.pow(1 - p, 3);
      el.textContent = Math.round(to * e) + suffix;
      if (p < 1) requestAnimationFrame(f);
    })(t0);
  }
  function render(n) {
    const L = n.learning,
      R = n.replay,
      A = n.audit,
      E = n.engineering;
    const statIO = new IntersectionObserver(
      es =>
        es.forEach(e => {
          if (!e.isIntersecting) return;
          statIO.disconnect();
          countUp(document.querySelector('[data-k="transfer"]'), Math.round(L.physarum.transfer * 100), "%");
          countUp(document.querySelector('[data-k="heal"]'), Math.round(R.physarum_after * 100), "%");
          countUp(document.querySelector('[data-k="audit"]'), Math.round(A.precision * 100), "%");
        }),
      { threshold: 0.4 }
    );
    statIO.observe(document.getElementById("stats"));
    set("transfer_static", `frozen graph: ${pct(L.static.transfer)}`);
    set("heal_static", `frozen graph: ${pct(R.static_after)} · after ${R.verdicts} verdicts`);
    set("audit_lift", `${A.lift}× better than chance · ${A.flagged} flagged`);
    set("decay_naive", `instead of ${E.naive_decay_writes.toLocaleString()} per step`);

    const bench = [
      {
        big: pct(L.physarum.transfer),
        ref: L.static.transfer,
        val: L.physarum.transfer,
        t: "Never-asked questions",
        d: `frozen ${pct(L.static.transfer)} · count-only ${pct(L.evidence.transfer)} · ${L.seeds} seeds`,
      },
      {
        big: pct(R.physarum_after),
        ref: R.static_after,
        val: R.physarum_after,
        t: "Real 2020→2026 changes",
        d: `${R.questions} head-of-state questions · votes to heal: ${R.votes_to_heal_median}`,
      },
      {
        big: pct(A.precision),
        ref: A.base_rate,
        val: A.precision,
        t: "Self-audit precision",
        d: `chance ${pct(A.base_rate)} · recall ${pct(A.recall)} · vs human labels`,
      },
      {
        big: `${pct(n.removal.learned)}`,
        ref: n.removal.wiped,
        val: n.removal.learned,
        t: "Wipe → restore",
        d: `learned ${pct(n.removal.learned)} → wiped ${pct(n.removal.wiped)} → restored ${pct(n.removal.restored)}`,
      },
    ];
    document.getElementById("bench").innerHTML = bench
      .map(
        b =>
          `<div class="bcard reveal in"><div class="big">${b.big}</div><div class="t">${b.t}</div><div class="d">${b.d}</div><div class="bar2"><i data-w="${b.val}"></i><b style="left:${(b.ref || 0) * 100}%"></b></div></div>`
      )
      .join("");
    const bio = new IntersectionObserver(
      es =>
        es.forEach(e => {
          if (e.isIntersecting) {
            e.target.querySelectorAll("i[data-w]").forEach(i => (i.style.width = +i.dataset.w * 100 + "%"));
            bio.disconnect();
          }
        }),
      { threshold: 0.3 }
    );
    bio.observe(document.getElementById("bench"));

    const G = n.rag || {};
    const rows = [
      [
        "Never-asked questions",
        pct(G.transfer),
        pct(L.static.transfer),
        pct(L.evidence.transfer),
        pct(L.physarum.transfer),
      ],
      [
        "Questions about other people",
        pct(G.unrelated),
        pct(L.static.unrelated),
        pct(L.evidence.unrelated),
        pct(L.physarum.unrelated),
      ],
      [
        `After facts change (+${n.drift.at[1]} questions)`,
        "–",
        pct(n.drift.static[1]),
        pct(n.drift.evidence[1]),
        pct(n.drift.physarum[1]),
      ],
      [
        `After facts change (+${n.drift.at[2]} questions)`,
        "–",
        pct(n.drift.static[2]),
        pct(n.drift.evidence[2]),
        pct(n.drift.physarum[2]),
      ],
      [
        "Real 2020→2026 heads of state",
        pct(G.hos_2026),
        pct(R.static_after),
        pct(R.evidence_after),
        pct(R.physarum_after),
      ],
      ["Context tokens per answer", G.context_tokens || "–", "–", "–", G.physarum_tokens || "–"],
      ["Learns from use", "no", "no", "yes", "yes"],
      ["Flags its own false facts", "no", "no", "–", `${pct(A.precision)} precision`],
    ];
    document.getElementById("cmpBody").innerHTML = rows
      .map(r => `<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td class="hl">${r[4]}</td></tr>`)
      .join("");
    document.getElementById("numbersFoot").textContent =
      `numbers generated ${n.generated} · store: ${n.store} · verifier: ${n.verifier} · reproduce: make numbers`;
  }
  fetch("/static/numbers.json")
    .then(r => (r.ok ? r.json() : Promise.reject()))
    .then(render)
    .catch(() => {
      document.getElementById("numbersFoot").textContent = "numbers.json not generated yet: run `make numbers`";
    });
  fetch("/api/info")
    .then(r => r.json())
    .then(i => {
      if (i.repo) document.getElementById("ghLink").href = i.repo;
    })
    .catch(() => {});
})();

// early-access form
const wl = document.getElementById("waitlist");
if (wl)
  wl.addEventListener("submit", async ev => {
    ev.preventDefault();
    const msg = document.getElementById("wmsg");
    const body = Object.fromEntries(new FormData(wl).entries());
    try {
      const r = await fetch("/api/waitlist", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.detail || "something went wrong");
      wl.reset();
      msg.textContent = "Thanks! You're on the list. We'll be in touch.";
      msg.classList.add("ok");
    } catch (e) {
      msg.textContent = e.message;
    }
  });

// live traction: real counts from this deployment, shown once there is something worth showing
(async () => {
  try {
    const t = await (await fetch("/api/traction")).json();
    const esc = s => String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
    const items = [
      [t.visitors, "people tried the live demo"],
      [t.graphs_built, "graphs built from visitors' own facts"],
      [t.demo_verdicts + t.playground_votes, "verdicts learned from"],
      [t.waitlist, "early-access requests"],
      [t.would_use.yes + t.would_use.maybe, `said they'd use it (of ${t.feedback} asked)`],
    ].filter(([n]) => n > 0);
    if (t.visitors < 10 && !t.testimonials.length) return;
    document.getElementById("tnums").innerHTML = items
      .map(([n, l]) => `<div><b>${n.toLocaleString()}</b><span>${l}</span></div>`)
      .join("");
    document.getElementById("quotes").innerHTML = t.testimonials
      .map(
        q => `<blockquote>"${esc(q.quote)}"<cite>${esc(q.name)}${q.role ? " · " + esc(q.role) : ""}</cite></blockquote>`
      )
      .join("");
    document.getElementById("traction").hidden = false;
  } catch {}
})();
